56	        // ---- the single "midlayer" decoder block ----
57	        // q/k/v share `2 * hidden_size` input columns (embed ++ hidden concat).
58	        let q_proj = load_tensor_2d(
59	            ctx,
60	            &shards,
61	            &weight_map,
