100	            inter,
101	            hidden,
102	        )?;
103	        let gate_up_proj = DeviceMatrix::vstack(ctx, &[&gate_proj, &up_proj])?;
104	        drop(gate_proj);
105	        drop(up_proj);
106	
107	        let o_proj = load_tensor_2d(
